const s = $('Set Monitor Config').first().json;
const wfs = $input.first().json.data || [];
const AI_TYPES = /openai|lmchat|langchain|anthropic|gemini|mistral|ollama|groq/i;
const windowStart = new Date(Date.now() - s.window_hours * 3600 * 1000).toISOString();

return wfs.filter(w => w.id !== $workflow.id).map(w => {
  const aiNode = (w.nodes || []).find(n => AI_TYPES.test(n.type));
  const p = aiNode?.parameters || {};
  const model = (typeof p.model === 'string' ? p.model : p.model?.value) || p.modelId?.value || s.default_model;
  const tags = (w.tags || []).map(t => t.name);
  return { json: {
    workflow_id: w.id, workflow_name: w.name, is_ai: !!aiNode, primary_model: model, tags,
    protected: tags.some(t => /no-auto-disable|critical/i.test(t)),
    window_start: windowStart, base_url: s.n8n_base_url
  }};
});

const s = $('Set Monitor Config').first().json;
const index = $('Build Workflow Index').all().map(i => i.json);
const windowStart = index[0]?.window_start || new Date(0).toISOString();

// USD per 1M tokens – estimate, keep in sync with your provider pricing
const PRICING = {
  'gpt-4o-mini': { in: 0.15, out: 0.60 }, 'gpt-4o': { in: 2.50, out: 10.00 },
  'gpt-4.1-mini': { in: 0.40, out: 1.60 }, 'gpt-4.1': { in: 2.00, out: 8.00 },
  'o3-mini': { in: 1.10, out: 4.40 }, 'gpt-5-mini': { in: 0.25, out: 2.00 }, 'gpt-5': { in: 1.25, out: 10.00 }
};
const pk = Object.keys(PRICING).sort((a, b) => b.length - a.length);
const costOf = (model, tin, tout) => {
  const p = PRICING[pk.find(k => String(model).toLowerCase().includes(k)) || 'gpt-4o-mini'];
  return (tin * p.in + tout * p.out) / 1e6;
};
function scanTokens(obj, model, acc, depth = 0) {
  if (!obj || typeof obj !== 'object' || depth > 14) return;
  const u = obj.tokenUsage || obj.usage;
  if (u && typeof u === 'object') {
    const tin = u.promptTokens ?? u.prompt_tokens ?? u.input_tokens ?? 0;
    const tout = u.completionTokens ?? u.completion_tokens ?? u.output_tokens ?? 0;
    if (tin || tout) { acc.push({ model: obj.model || model, tin, tout }); return; }
  }
  for (const v of (Array.isArray(obj) ? obj : Object.values(obj))) scanTokens(v, obj.model || model, acc, depth + 1);
}

const byId = {};
for (const w of index) byId[w.workflow_id] = { ...w, total: 0, failed: 0, success: 0, durations: [], tokens_in: 0, tokens_out: 0, cost_usd: 0, last_error_at: '', error_ids: [] };

const seen = new Set();
for (const page of $input.all()) {
  const list = page.json.data;
  if (!Array.isArray(list)) continue;
  for (const ex of list) {
    if (!ex || seen.has(ex.id)) continue;
    seen.add(ex.id);
    if (!ex.startedAt || ex.startedAt < windowStart) continue;
    const w = byId[ex.workflowId];
    if (!w) continue;
    w.total++;
    if (['error', 'crashed'].includes(ex.status)) {
      w.failed++;
      w.error_ids.push({ id: String(ex.id), at: ex.startedAt });
      if (ex.startedAt > w.last_error_at) w.last_error_at = ex.startedAt;
    } else if (ex.status === 'success' || ex.finished) w.success++;
    if (ex.stoppedAt) w.durations.push((new Date(ex.stoppedAt) - new Date(ex.startedAt)) / 1000);
    if (ex.data?.resultData?.runData) {
      const acc = [];
      scanTokens(ex.data.resultData.runData, w.primary_model, acc);
      for (const t of acc) { w.tokens_in += t.tin; w.tokens_out += t.tout; w.cost_usd += costOf(t.model, t.tin, t.tout); }
    }
  }
}

const pct = (arr, q) => { if (!arr.length) return 0; const a = [...arr].sort((x, y) => x - y); return a[Math.min(a.length - 1, Math.floor(q * a.length))]; };
const workflows = Object.values(byId).map(w => {
  const er = w.total ? w.failed / w.total : 0;
  const crit = [], warn = [];
  if (s.mode === 'guard') {
    if (w.total >= s.max_exec_per_hour) crit.push(`${w.total} executions in the last hour (limit ${s.max_exec_per_hour})`);
    else if (w.total >= s.max_exec_per_hour * s.warn_ratio) warn.push(`${w.total} executions/hour – ${Math.round(w.total / s.max_exec_per_hour * 100)}% of limit`);
    if (w.failed >= s.min_failures_for_runaway && er >= s.max_error_rate) crit.push(`${w.failed} failures, ${(er * 100).toFixed(0)}% error rate`);
    else if (w.failed >= s.warn_min_failures && er >= s.warn_error_rate) warn.push(`${w.failed} failures, ${(er * 100).toFixed(0)}% error rate`);
    if (w.cost_usd >= s.hourly_token_budget_usd) crit.push(`~$${w.cost_usd.toFixed(2)} LLM spend in the last hour (budget $${s.hourly_token_budget_usd})`);
    else if (w.cost_usd >= s.hourly_token_budget_usd * s.warn_ratio) warn.push(`~$${w.cost_usd.toFixed(2)} LLM spend/hour – ${Math.round(w.cost_usd / s.hourly_token_budget_usd * 100)}% of budget`);
  }
  const { durations, error_ids, ...rest } = w;
  const recent = error_ids.sort((a, b) => (a.at < b.at ? 1 : -1)).slice(0, 3).map(e => e.id);
  return { ...rest, error_rate: +er.toFixed(3),
    avg_seconds: +(durations.reduce((a, b) => a + b, 0) / (durations.length || 1)).toFixed(1),
    p95_seconds: +pct(durations, 0.95).toFixed(1), slow: pct(durations, 0.95) >= s.slow_p95_seconds,
    cost_usd: +w.cost_usd.toFixed(4), crit_reasons: crit, warn_reasons: warn,
    last_error_id: recent[0] || '', recent_error_ids: recent };
}).sort((a, b) => b.failed - a.failed || b.cost_usd - a.cost_usd);

const sum = k => workflows.reduce((t, w) => t + (w[k] || 0), 0);
const totals = { workflows: workflows.length, executions: sum('total'), failed: sum('failed'),
  error_rate: sum('total') ? +(sum('failed') / sum('total')).toFixed(3) : 0, cost_usd: +sum('cost_usd').toFixed(2),
  tokens: sum('tokens_in') + sum('tokens_out'), slow_workflows: workflows.filter(w => w.slow).length };

return [{ json: { mode: s.mode, window_start: windowStart, generated_at: new Date().toISOString(), base_url: s.n8n_base_url,
  digest_email: s.digest_email, totals, workflows } }];

const m = $('Compute Health & Cost Metrics').first().json;
const s = $('Set Monitor Config').first().json;
const log = $('Read Guard Log Sheet').all().map(i => i.json).filter(r => r.workflow_id);
const now = Date.now();
const cooldownMs = s.alert_cooldown_hours * 3600 * 1000;

const recentWarn = new Set(log
  .filter(r => r.severity === 'warning' && now - new Date(r.logged_at).getTime() < cooldownMs)
  .map(r => String(r.workflow_id)));
const disables7d = {};
for (const r of log) {
  if (r.action === 'auto_disable' && now - new Date(r.logged_at).getTime() < 7 * 86400000)
    disables7d[r.workflow_id] = (disables7d[r.workflow_id] || 0) + 1;
}

const out = [];
for (const w of m.workflows) {
  if (!w.crit_reasons.length && !w.warn_reasons.length) continue;
  const severity = w.crit_reasons.length ? 'critical' : 'warning';
  if (severity === 'warning' && recentWarn.has(String(w.workflow_id))) continue; // cooldown
  const action = severity === 'critical' ? (w.protected ? 'alert_only_protected' : 'auto_disable') : 'alert_only';
  const prior = disables7d[w.workflow_id] || 0;
  out.push({ json: {
    workflow_id: w.workflow_id, workflow_name: w.workflow_name, base_url: m.base_url,
    severity, action, reasons: [...w.crit_reasons, ...w.warn_reasons],
    total: w.total, failed: w.failed, error_rate: w.error_rate, cost_usd: w.cost_usd,
    last_error_id: w.last_error_id || 'none',
    disables_7d: prior, repeat_offender: action === 'auto_disable' && prior >= 1
  }});
}
// critical first
return out.sort((a, b) => (a.severity === b.severity ? 0 : a.severity === 'critical' ? -1 : 1));

const m = $('Compute Health & Cost Metrics').first().json;
const MAX_WORKFLOWS = 6;
const samples = m.workflows.filter(w => w.failed > 0 && w.recent_error_ids?.length).slice(0, MAX_WORKFLOWS)
  .flatMap(w => w.recent_error_ids.map(id => ({ json: { execution_id: id, workflow_id: w.workflow_id, workflow_name: w.workflow_name, base_url: m.base_url } })));
// keep the chain alive when there were no failures
return samples.length ? samples : [{ json: { execution_id: 'none', workflow_id: '', workflow_name: '', base_url: m.base_url } }];

function extractError(ex) {
  const rd = ex?.data?.resultData || {};
  let node = rd.error?.node?.name || '';
  let msg = rd.error?.message || rd.error?.description || '';
  if (!msg) {
    for (const [name, runs] of Object.entries(rd.runData || {})) {
      const r = (runs || []).find(x => x && x.error);
      if (r) { node = name; msg = r.error.message || r.error.description || ''; break; }
    }
  }
  return { node: node || rd.lastNodeExecuted || 'n/a', message: String(msg || '').slice(0, 400) };
}
const w = $('Classify & Dedupe Incidents').item.json;
const e = $json && $json.data ? extractError($json) : { node: 'n/a', message: w.failed ? 'could not load execution detail' : 'no failed executions in window' };
return { json: { ...w, failing_node: e.node, error_message: e.message } };

function extractError(ex) {
  const rd = ex?.data?.resultData || {};
  let node = rd.error?.node?.name || '';
  let msg = rd.error?.message || rd.error?.description || '';
  if (!msg) {
    for (const [name, runs] of Object.entries(rd.runData || {})) {
      const r = (runs || []).find(x => x && x.error);
      if (r) { node = name; msg = r.error.message || r.error.description || ''; break; }
    }
  }
  return { node: node || rd.lastNodeExecuted || 'n/a', message: String(msg || '').slice(0, 400) };
}
const m = $('Compute Health & Cost Metrics').first().json;
const s = $('Set Monitor Config').first().json;
const today = m.generated_at.slice(0, 10);
const avg = a => a.length ? a.reduce((x, y) => x + y, 0) / a.length : 0;
const pctf = v => (v * 100).toFixed(1) + '%';

// ── Trends vs Metrics_History ──
const hist = $('Read Metrics History Sheet').all().map(i => i.json).filter(r => r.snapshot_date && r.workflow_id);
const dates = [...new Set(hist.map(r => String(r.snapshot_date).slice(0, 10)))].filter(d => d < today).sort();
const baseDates = dates.slice(-4);
const prevDate = dates[dates.length - 1];
const inBase = r => baseDates.includes(String(r.snapshot_date).slice(0, 10));

const anomalies = [];
for (const w of m.workflows) {
  const rows = hist.filter(r => String(r.workflow_id) === String(w.workflow_id) && inBase(r));
  if (!rows.length) { if (baseDates.length && w.total) anomalies.push({ type: 'new_workflow', severity: 'info', workflow: w.workflow_name, detail: `${w.total} runs, no history yet` }); continue; }
  const bE = avg(rows.map(r => +r.error_rate || 0)), bC = avg(rows.map(r => +r.cost_usd || 0));
  const bP = avg(rows.map(r => +r.p95_seconds || 0)), bR = avg(rows.map(r => +r.executions || 0));
  if (w.failed >= s.warn_min_failures && w.error_rate > Math.max(bE * 2, bE + 0.1))
    anomalies.push({ type: 'error_spike', severity: 'high', workflow: w.workflow_name, detail: `error rate ${pctf(w.error_rate)} vs ${pctf(bE)} baseline` });
  if (bR >= 10 && w.total === 0)
    anomalies.push({ type: 'silent_workflow', severity: 'high', workflow: w.workflow_name, detail: `active but 0 runs (baseline ${Math.round(bR)}/week) – trigger may be broken` });
  if (w.cost_usd > 1 && w.cost_usd > bC * 1.5)
    anomalies.push({ type: 'cost_spike', severity: 'medium', workflow: w.workflow_name, detail: `$${w.cost_usd.toFixed(2)} vs $${bC.toFixed(2)} baseline` });
  if (w.p95_seconds > 30 && bP > 0 && w.p95_seconds > bP * 1.5)
    anomalies.push({ type: 'latency_regression', severity: 'medium', workflow: w.workflow_name, detail: `p95 ${w.p95_seconds}s vs ${bP.toFixed(1)}s baseline` });
  if (bR > 0 && w.total > 50 && w.total > bR * 3)
    anomalies.push({ type: 'volume_spike', severity: 'medium', workflow: w.workflow_name, detail: `${w.total} runs vs ${Math.round(bR)} baseline` });
}
const sevRank = { high: 0, medium: 1, info: 2 };
anomalies.sort((a, b) => sevRank[a.severity] - sevRank[b.severity]);

const prevT = hist.find(r => r.workflow_id === '__total__' && String(r.snapshot_date).slice(0, 10) === prevDate);
const wow = prevT ? {
  executions: m.totals.executions - (+prevT.executions || 0),
  failed: m.totals.failed - (+prevT.failed || 0),
  error_rate_pts: +((m.totals.error_rate - (+prevT.error_rate || 0)) * 100).toFixed(1),
  cost_usd: +(m.totals.cost_usd - (+prevT.cost_usd || 0)).toFixed(2)
} : null;

// ── Error signature clustering ──
const sampleMeta = $('Build Failure Sample List').all().map(i => i.json);
const signature = msg => String(msg).toLowerCase()
  .replace(/https?:\/\/\S+/g, '<url>').replace(/["'`][^"'`]{0,80}["'`]/g, '"…"')
  .replace(/[0-9a-f]{8,}/g, '#').replace(/\d+/g, '#').replace(/\s+/g, ' ').trim().slice(0, 110);
const category = msg => /401|403|unauthori|forbidden|api key|credential|token.*(expired|invalid)/i.test(msg) ? 'credentials'
  : /429|rate.?limit|quota|too many requests/i.test(msg) ? 'rate_limit'
  : /timeout|timed out|etimedout|econnreset|econnrefused|socket|enotfound|502|503|504/i.test(msg) ? 'network/timeout'
  : /json|parse|unexpected token|invalid syntax/i.test(msg) ? 'data_format'
  : /cannot read prop|undefined|is not a function|referenceerror|expression/i.test(msg) ? 'code/expression'
  : 'other';
const clusters = {};
$input.all().forEach((it, i) => {
  if (!it.json || !it.json.data) return;
  const e = extractError(it.json);
  if (!e.message) return;
  const key = signature(e.message);
  const c = clusters[key] ||= { signature: key, category: category(e.message), sample: e.message.slice(0, 200), count: 0, nodes: new Set(), workflows: new Set() };
  c.count++; c.nodes.add(e.node); c.workflows.add(sampleMeta[i]?.workflow_name || it.json.workflowId);
});
const error_clusters = Object.values(clusters)
  .map(c => ({ ...c, nodes: [...c.nodes], workflows: [...c.workflows], cross_workflow: c.workflows.size > 1 }))
  .sort((a, b) => b.workflows.length - a.workflows.length || b.count - a.count).slice(0, 8);

return [{ json: { ...m, snapshot_date: today, has_history: baseDates.length > 0, baseline_weeks: baseDates.length, wow, anomalies, error_clusters } }];

