const m = $('Analyze Trends & Error Clusters').first().json;
let ai = $json.message?.content ?? {};
if (typeof ai === 'string') { try { ai = JSON.parse(ai); } catch (e) { ai = {}; } }
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;');
const link = w => `<a href="${m.base_url}/workflow/${w.workflow_id}">${esc(w.workflow_name)}</a>`;
const table = (title, rows, cols) => rows.length ? `<h3>${title}</h3><table border="1" cellpadding="6" style="border-collapse:collapse;font-size:13px">
<tr style="background:#f0f0f0">${cols.map(c => `<th>${c[0]}</th>`).join('')}</tr>
${rows.map(r => `<tr>${cols.map(c => `<td>${c[1](r)}</td>`).join('')}</tr>`).join('')}</table>` : '';
const list = (t, a) => (a && a.length) ? `<h3>${t}</h3><ul>${a.map(x => `<li>${esc(x)}</li>`).join('')}</ul>` : '';
const t = m.totals, wow = m.wow;
const delta = (v, unit = '', invert = false) => {
  if (wow === null || v === undefined) return '';
  const bad = invert ? v < 0 : v > 0;
  return `<div style="font-size:11px;color:${v === 0 ? '#888' : bad ? '#c0392b' : '#27ae60'}">${v > 0 ? '▲' : v < 0 ? '▼' : '■'} ${Math.abs(v)}${unit} WoW</div>`;
};
const card = (k, v, d = '') => `<td style="padding:10px 16px;background:#f6f6f6;text-align:center"><div style="font-size:20px;font-weight:bold">${v}</div><div style="font-size:12px;color:#666">${k}</div>${d}</td>`;
const sevColor = s => s === 'high' ? '#c0392b' : s === 'medium' ? '#d35400' : '#2980b9';

const failing = m.workflows.filter(w => w.failed > 0).slice(0, 10);
const slow = [...m.workflows].filter(w => w.total > 0).sort((a, b) => b.p95_seconds - a.p95_seconds).slice(0, 8);
const spend = [...m.workflows].filter(w => w.cost_usd > 0).sort((a, b) => b.cost_usd - a.cost_usd).slice(0, 8);

const html = `<div style="font-family:Arial,sans-serif;max-width:860px">
<h2>n8n weekly health & cost digest</h2>
<p>${esc(ai.headline || '')} <b>Health score: ${ai.health_score ?? 'n/a'}/100</b></p>
<table cellspacing="6"><tr>
${card('Executions', t.executions, wow && delta(wow.executions, '', true))}
${card('Failed', t.failed, wow && delta(wow.failed))}
${card('Error rate', (t.error_rate * 100).toFixed(1) + '%', wow && delta(wow.error_rate_pts, ' pts'))}
${card('Est. LLM spend', '$' + t.cost_usd, wow && delta(wow.cost_usd, '$'))}
${card('Anomalies', m.anomalies.filter(a => a.severity !== 'info').length)}
${card('Error clusters', m.error_clusters.length)}</tr></table>
${m.has_history ? '' : '<p style="color:#888">First run – trends and anomalies start next week once history exists.</p>'}
${list('Key findings', ai.key_findings)}${list('Likely root causes', ai.root_causes)}${list('Anomaly actions', ai.anomaly_actions)}${list('Cost actions', ai.cost_actions)}
${table('Anomalies vs 4-week baseline', m.anomalies.slice(0, 15), [['Severity', a => `<b style="color:${sevColor(a.severity)}">${a.severity.toUpperCase()}</b>`], ['Type', a => a.type.replace(/_/g, ' ')], ['Workflow', a => esc(a.workflow)], ['Detail', a => esc(a.detail)]])}
${table('Error clusters (latest failures)', m.error_clusters, [['Category', c => `<b>${c.category}</b>${c.cross_workflow ? '<br><small style="color:#c0392b">cross-workflow</small>' : ''}`], ['Seen', c => c.count], ['Workflows', c => esc(c.workflows.join(', '))], ['Node(s)', c => esc(c.nodes.join(', '))], ['Sample error', c => `<code style="font-size:11px">${esc(c.sample)}</code>`]])}
${table('Top failing workflows', failing, [['Workflow', link], ['Runs', w => w.total], ['Failed', w => w.failed], ['Error rate', w => (w.error_rate * 100).toFixed(1) + '%'], ['Last error', w => (w.last_error_at || '').slice(0, 16).replace('T', ' ')]])}
${table('Slowest workflows (p95)', slow, [['Workflow', link], ['Runs', w => w.total], ['Avg s', w => w.avg_seconds], ['p95 s', w => w.p95_seconds]])}
${table('LLM token spend by workflow', spend, [['Workflow', link], ['Model', w => esc(w.primary_model)], ['Tokens', w => (w.tokens_in + w.tokens_out).toLocaleString()], ['Est. cost', w => '$' + w.cost_usd]])}
<p style="color:#888;font-size:12px">Window from ${m.window_start.slice(0, 10)} · Cost is estimated from tokenUsage in execution data.</p></div>`;

const high = m.anomalies.filter(a => a.severity === 'high');
const slack_text = `:bar_chart: *n8n weekly digest* – health ${ai.health_score ?? 'n/a'}/100\n${ai.headline || ''}\n• ${t.executions} runs · ${t.failed} failed (${(t.error_rate * 100).toFixed(1)}%) · ~$${t.cost_usd} LLM spend${wow ? ` · WoW failures ${wow.failed >= 0 ? '+' : ''}${wow.failed}` : ''}\n${high.length ? `:rotating_light: ${high.map(a => `${a.workflow}: ${a.detail}`).slice(0, 5).join('\n:rotating_light: ')}\n` : ''}${m.error_clusters.filter(c => c.cross_workflow).map(c => `:link: ${c.category} error hitting ${c.workflows.length} workflows`).slice(0, 3).join('\n')}\nFull report sent to ${m.digest_email}`;

return [{ json: { to: m.digest_email, subject: `n8n weekly: ${t.failed} failures · ${(t.error_rate * 100).toFixed(1)}% error rate · ~$${t.cost_usd} LLM · ${high.length} high anomalies`, html, slack_text } }];

